  List.NoDup pages ->
  (forall pg, In pg pages -> pg mod 4096 = 0) ->
  (forall pg, In pg pages -> exists b s, In (b, s) l /\ u b <= pg /\ pg + 4096 <= u b + u s /\
                                        forall x, pg <= x < pg + 4096 -> P x = true) ->
  4096 * Z.of_nat (length pages) <= BA.sum_count P l.
